const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');
const { default: MagicString, Bundle } = require('magic-string');

const root = path.resolve(__dirname, '..');
const output = path.join(root, 'vend-proofing-core/js');

function buildJs({ check = false } = {}) {
	const configPath = path.join(root, 'assets.config.js');
	delete require.cache[require.resolve(configPath)];
	const { js, copy = {} } = require(configPath);
	const outputs = [];
	for (const [name, entry] of Object.entries(js)) {
		const filename = path.join(output, `${name}.js`);
		const bundle = new Bundle({
			intro: '// Generated by npm run build:js. Edit src/ and assets.config.js instead.\n',
			separator: '\n;\n',
		});
		const sources = [...(entry.prepend || []), ...entry.source, ...(entry.append || [])];
		if (new Set(sources).size !== sources.length) throw new Error(`Duplicate source in ${name}`);
		for (const source of sources) {
			const sourcePath = path.join(root, source);
			const code = fs.readFileSync(sourcePath, 'utf8');
			const content = new MagicString(code, { filename: sourcePath });
			// Replace upstream map annotations with the map for this bundle.
			for (const match of code.matchAll(/\/\/[#@]\s*sourceMappingURL=[^\r\n]*/g)) {
				content.remove(match.index, match.index + match[0].length);
			}
			bundle.addSource(content);
		}
		const code = bundle.toString() + `\n//# sourceMappingURL=${name}.js.map\n`;
		// Parse every bundle before replacing any previous build.
		new vm.Script(code, { filename });
		const map = bundle.generateMap({ file: filename, includeContent: false, hires: false });
		outputs.push([filename, code], [filename + '.map', map.toString() + '\n']);
	}
	for (const [name, source] of Object.entries(copy)) {
		const contents = fs.readFileSync(path.join(root, source), 'utf8');
		new vm.Script(contents, { filename: name });
		outputs.push([path.join(output, name), contents]);
	}
	if (!check) fs.mkdirSync(output, { recursive: true });
	for (const [filename, contents] of outputs) {
		const existing = fs.existsSync(filename) ? fs.readFileSync(filename, 'utf8') : null;
		if (existing === contents) continue;
		if (check) throw new Error(`${filename} needs rebuilding: npm run build:js`);
		fs.writeFileSync(filename, contents);
	}
}

module.exports = { buildJs };
if (require.main === module) {
	try {
		buildJs({ check: process.argv.includes('--check') });
	} catch (error) {
		console.error(error);
		process.exitCode = 1;
	}
}
